  Lemma mi_R2 : forall regs t1v a6v i (mx : word), (d = 2)%Z -> (0 <= i < h)%Z ->
    LInv regs t1v a6v -> getr regs 12 = Z_to_bv 64 i -> getr regs 9 = Z_to_bv 64 (data + 4 * wpl * i) ->
    getr regs 31 = mx -> (bv_unsigned mx <= maxval)%Z ->
    exists regs' (mx' : word),
